const texto = $input.first().json.output;
const itens = texto.split(/\\/);
return itens.filter(item => item.trim() !== '').map(item => ({ item: item.trim() }));

const coleta = $('Coleta').item.json;
const nome = coleta.nome || 'Não identificado';
const tel = coleta.telefone || '';
const tipo = coleta.tipo || 'midia';
const msg = coleta.mensagem || '';

const tipoLabel = { imageMessage: '📷 Imagem', videoMessage: '🎬 Vídeo', audioMessage: '🎵 Áudio' }[tipo] || '📎 Mídia';
const temLegenda = msg && !msg.startsWith('📷') && !msg.startsWith('🎬') && !msg.startsWith('🎵');
const legenda = temLegenda ? '\nLegenda: _' + msg + '_' : '';
const telLimpo = tel.replace('@s.whatsapp.net','').replace(/^55/,'').replace(/\D/g,'');

const alertText = '🔔 *Mídia Recebida — Damares Estética*\n\n' +
  '*Cliente:* ' + nome + '\n' +
  '*Telefone:* ' + telLimpo + legenda + '\n' +
  '*Mídia:* ' + tipoLabel + '\n\n' +
  '_Mensagem de mídia recebida — verifique no WhatsApp se necessário._';

return [{ json: { alertText } }];

const inp = $input.first().json;

function normDate(v) {
  if (!v) return '';
  v = v.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const parts = v.split('/');
  if (parts.length === 2) {
    const now = new Date();
    const day   = ('0' + parts[0].trim()).slice(-2);
    const month = ('0' + parts[1].trim()).slice(-2);
    let year = now.getFullYear();
    const candidate = new Date(year + '-' + month + '-' + day + 'T12:00:00');
    if (candidate < now) year++;
    return year + '-' + month + '-' + day;
  }
  if (parts.length === 3) {
    const day   = ('0' + parts[0].trim()).slice(-2);
    const month = ('0' + parts[1].trim()).slice(-2);
    const year  = parts[2].trim();
    return year + '-' + month + '-' + day;
  }
  return '';
}

// Real WhatsApp number from main workflow Coleta node
let whatsappPhone = '';
try {
  whatsappPhone = $('Coleta').first().json.telefone || '';
  whatsappPhone = whatsappPhone.replace('@s.whatsapp.net', '').replace(/\D/g, '');
} catch(e) {}

// Use LLM-provided phone only if it looks real; otherwise fall back to WhatsApp number
const rawPhone = (inp.client_phone || inp.telefone || '').replace(/\D/g, '');
const isPlaceholder = !rawPhone || rawPhone === '11999999999' || rawPhone === '5511999999999' || rawPhone.length < 10;
const client_phone = isPlaceholder ? whatsappPhone : rawPhone;

return [{ json: {
  client_name:  inp.client_name  || inp.nome        || '',
  client_phone,
  service:      inp.service      || inp.procedimento || '',
  date:         normDate(inp.date || inp.data || ''),
  time:         inp.time         || inp.horario     || '',
  address:      inp.address      || inp.endereco    || '',
  notes:        inp.notes        || inp.observacoes  || ''
}}];

const d = $input.first().json;
if (!d.date || !d.time) return [{ json: { sucesso: false, mensagem: 'Data e horário são obrigatórios.' } }];

function getDuracao(service) {
  const s = (service || '').toLowerCase();
  if (s.includes('1h30') || s.includes('1 hora e meia')) return 90;
  if (s.includes('1h20') || s.includes('1 hora e 20'))   return 80;
  if (s.includes('pós-operatório') || s.includes('pos-operatorio') || s.includes('operatorio')) return 90;
  if (s.includes('facial') && !s.includes('corporal')) return 40;
  return 60;
}

function getGrupo(addr) {
  if (!addr) return 'B';
  const a = (addr).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if (/mooca|tatuape|analia/.test(a)) return 'A';
  if (/itaim|jardim europa|jardins|vila nova conceicao|higienopolis/.test(a)) return 'C';
  return 'B';
}

function getSinal(service, grupo, notes) {
  const texto = ((service || '') + ' ' + (notes || '')).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const isPlano = texto.includes('plano') || texto.includes('5 sess') || texto.includes('pacote') || texto.includes(' 5x') || texto.includes('5 ses');
  const is1h30  = texto.includes('1h30') || texto.includes('hora e meia');
  const is1h20  = texto.includes('1h20') || texto.includes('hora e 20') ||
                  (texto.includes('corporal') && texto.includes('facial'));
  const isPosOp = texto.includes('operatorio') || texto.includes('operatório');
  const isDren  = texto.includes('drenagem') || texto.includes('corporal') || texto.includes('linfatica');

  let avulsa = 0, plano = 0;

  if (isPosOp) {
    avulsa = 200; plano = 950;
  } else if (isDren) {
    if (grupo === 'C') { avulsa = is1h20 ? 190 : 150; plano = is1h20 ? 902.5 : 712.5; }
    else               { avulsa = is1h20 ? 150 : 125; plano = is1h20 ? 712.5 : 595; }
  } else {
    // Massagem Relaxante
    if (grupo === 'A') { avulsa = is1h30 ? 150 : 110; plano = is1h30 ? 712.5 : 522.5; }
    if (grupo === 'B') { avulsa = is1h30 ? 160 : 125; plano = is1h30 ? 760   : 595; }
    if (grupo === 'C') { avulsa = is1h30 ? 215 : 175; plano = is1h30 ? 1022.5: 832.5; }
  }

  const valor = isPlano ? plano : avulsa;
  const tipo  = isPlano ? 'plano 5 sessões' : 'sessão avulsa';
  return { valor, tipo, avulsa, plano };
}

const dur   = getDuracao(d.service);
const grupo = getGrupo(d.address);
const sinal = getSinal(d.service, grupo, d.notes);

const startDT = d.date + 'T' + d.time + ':00-03:00';
const [hh, mm] = d.time.split(':').map(Number);
const endMin   = hh * 60 + mm + dur;
const endDT    = d.date + 'T' + String(Math.floor(endMin/60)).padStart(2,'0') + ':' + String(endMin%60).padStart(2,'0') + ':00-03:00';
const endTime  = String(Math.floor(endMin/60)).padStart(2,'0') + ':' + String(endMin%60).padStart(2,'0');

let dateDisplay = d.date;
try { dateDisplay = new Date(d.date + 'T12:00:00').toLocaleDateString('pt-BR', { weekday:'long', day:'numeric', month:'long', year:'numeric' }); } catch(e){}

function fmtBRL(v) { return 'R$ ' + v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

const title = '💆 ' + d.service + ' — ' + d.client_name;
const descLines = [
  'Procedimento: ' + d.service,
  'Cliente: ' + d.client_name,
  'Telefone: ' + d.client_phone,
  d.address ? 'Endereço: ' + d.address : '',
  'Grupo: ' + grupo,
  '💳 Sinal aguardado: ' + fmtBRL(sinal.valor) + ' (' + sinal.tipo + ')',
  '⏳ Status: AGUARDANDO PAGAMENTO DO SINAL',
  d.notes ? 'Obs: ' + d.notes : '',
  '',
  'Agendado via WhatsApp — Damares Estética Home Care'
];
const description = descLines.filter(Boolean).join('\n');

return [{ json: { ...d, startDT, endDT, endTime, dur, grupo, dateDisplay, title, description,
  sinalValor: sinal.valor, sinalTipo: sinal.tipo, sinalFmt: fmtBRL(sinal.valor) } }];

const ev   = $input.first().json;
const prep = $('Prepara Dados do Evento').first().json;

const sinalFmt = prep.sinalFmt || 'R$ 0,00';
const mapsUrl  = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(prep.address || '');

const mensagem =
  '⏳ *Agendamento pendente de confirmação*\n\n' +
  '📋 *Resumo:*\n' +
  '• Procedimento: ' + prep.service + '\n' +
  '• Data: ' + prep.dateDisplay + '\n' +
  '• Horário: ' + prep.time + ' às ' + prep.endTime + '\n' +
  '• Endereço: ' + prep.address + '\n\n' +
  '💳 *Para confirmar sua reserva, realize o pagamento do sinal:*\n' +
  '• PIX (telefone): *11999950549*\n' +
  '• Banco: C6 Bank\n' +
  '• Valor do sinal (50%): *' + sinalFmt + '*\n' +
  'Após o pagamento, me envie a confirmação por aqui 😊🌿';

const notificacao =
  '📅 *Novo Agendamento — Damares Estética*\n\n' +
  '• Procedimento: ' + prep.service + '\n' +
  '• Data: ' + prep.dateDisplay + '\n' +
  '• Horário: ' + prep.time + ' às ' + prep.endTime + '\n' +
  '• Cliente: ' + prep.client_name + '\n' +
  '• Telefone: ' + prep.client_phone + '\n' +
  '• Endereço: ' + prep.address + '\n' +
  '• 📍 Maps: ' + mapsUrl + '\n' +
  '• 💳 Sinal aguardado: *' + sinalFmt + '*\n' +
  '• ⏳ Status: AGUARDANDO PAGAMENTO' +
  (prep.notes ? '\n• Obs: ' + prep.notes : '');

return [{ json: { sucesso: true, event_id: ev.id || 'criado', mensagem, notificacao, ...prep } }];

const lead = $input.first().json;

const mensagem =
  'Olá! 😊\n' +
  'Sou Damares, ex-terapeuta do SPA Express e atualmente atuo como terapeuta esteticista especializada em massagens e procedimentos estéticos a domicílio.\n\n' +
  'Levo conforto, cuidado e bem-estar até você, com atendimento personalizado no conforto da sua casa ✨\n\n' +
  'Fique à vontade para conhecer melhor o meu trabalho pelas minhas redes:\n\n' +
  '📲 Instagram: @damaresestetica\n' +
  '🌐 Site: damaresestetica.com\n\n' +
  'Posso te apresentar os serviços e valores disponíveis? Será um prazer te atender! 💆🏻‍♀️';

const telefoneWpp = lead.telefone.replace(/\D/g,'') + '@s.whatsapp.net';

return [{ json: { ...lead, mensagem, telefoneWpp } }];

const response = $input.first().json;
const items = response.items || [];

// Bairro do PRÓXIMO cliente (passado pelo agente)
const bairroDestino = ($('Entrada Tools').first().json.bairro || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// Determina grupo pelo bairro
function getGrupo(texto) {
  if (!texto) return 'B';
  const t = texto.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if (/mooca|tatuape|analia/.test(t))                              return 'A';
  if (/itaim|jardim europa|jardins|vila nova conceicao|higienopolis/.test(t)) return 'C';
  return 'B';
}

// Matriz de tempo de deslocamento em minutos entre grupos
const MATRIZ = {
  'A': { 'A': 45, 'B': 60, 'C': 90 },
  'B': { 'A': 60, 'B': 45, 'C': 60 },
  'C': { 'A': 90, 'B': 60, 'C': 45 }
};

const grupoDestino = getGrupo(bairroDestino);

function toBRT(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  if (isNaN(d)) return dateStr.slice(11, 16);
  const h = ((d.getUTCHours() - 3 + 24) % 24);
  const m = d.getUTCMinutes();
  return ('0' + h).slice(-2) + ':' + ('0' + m).slice(-2);
}

function addMinutes(dateStr, mins) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  if (isNaN(d)) return '';
  d.setMinutes(d.getMinutes() + mins);
  return d.toISOString();
}

if (items.length === 0) {
  return [{ json: {
    eventos: [], total: 0,
    grupo_destino: grupoDestino,
    mensagem: 'Nenhum evento encontrado. Todos os horários estão disponíveis.'
  } }];
}

const eventos = items.map(e => {
  const fim = e.end?.dateTime || e.end?.date || '';

  // Determina grupo de origem: tenta location, depois description
  const loc  = (e.location || '').toLowerCase();
  const desc = (e.description || '').toLowerCase();
  const textoOrigem = loc || (desc.match(/endere[cç]o:\s*([^\n]+)/)?.[1] || '') ||
                     (desc.match(/grupo:\s*([abc])/i)?.[1] || '');
  const grupoOrigem = getGrupo(textoOrigem) || (desc.match(/grupo:\s*([abc])/i)?.[1]?.toUpperCase()) || 'B';

  const bufferMin = MATRIZ[grupoOrigem]?.[grupoDestino] ?? 60;
  const proximoISO = addMinutes(fim, bufferMin);

  return {
    titulo:             e.summary || 'Compromisso',
    inicio_brt:         toBRT(e.start?.dateTime || e.start?.date),
    fim_brt:            toBRT(fim),
    grupo_origem:       grupoOrigem,
    buffer_minutos:     bufferMin,
    proximo_disponivel: toBRT(proximoISO)
  };
}).filter(e => e.inicio_brt);

return [{ json: {
  eventos,
  total: eventos.length,
  grupo_destino: grupoDestino,
  regra: 'Próximo atendimento só pode iniciar no campo proximo_disponivel de cada evento (considera deslocamento por região)'
} }];

// Normaliza a data de cancelamento para ISO 8601 e calcula o intervalo do dia
const d = $input.first().json;

function normDate(v) {
  if (!v) return '';
  v = v.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const parts = v.split('/');
  if (parts.length === 2) {
    const now = new Date();
    const day   = ('0' + parts[0].trim()).slice(-2);
    const month = ('0' + parts[1].trim()).slice(-2);
    let year = now.getFullYear();
    const candidate = new Date(year + '-' + month + '-' + day + 'T12:00:00');
    if (candidate < now) year++;
    return year + '-' + month + '-' + day;
  }
  if (parts.length === 3) {
    return parts[2].trim() + '-' + ('0' + parts[1].trim()).slice(-2) + '-' + ('0' + parts[0].trim()).slice(-2);
  }
  return '';
}

const date = normDate(d.cancel_date || '');
if (!date) return [{ json: { sucesso: false, mensagem: 'Data inválida para cancelamento.' } }];

return [{ json: {
  client_name: d.client_name || '',
  cancel_date: date,
  cancel_time: d.cancel_time || '',
  timeMin: date + 'T00:00:00-03:00',
  timeMax: date + 'T23:59:59-03:00'
} }];

const resp = $input.first().json;
const ctx  = $('Normaliza Cancelamento').first().json;

const items   = resp.items || [];
const timeKey = (ctx.cancel_time || '').trim().slice(0, 5); // HH:MM

// Remove acentos para comparação (ex: "Flávio" → "flavio")
function norm(s) {
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

const nameKey = norm(ctx.client_name);
// Palavras significativas (>2 chars) sem acento
const nameParts = nameKey.split(/\s+/).filter(p => p.length > 2);

// Convert ISO dateTime to BRT HH:MM (UTC-3)
function toBRT(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  if (isNaN(d)) return dateStr.slice(11, 16);
  const h = ((d.getUTCHours() - 3 + 24) % 24);
  const m = d.getUTCMinutes();
  return ('0' + h).slice(-2) + ':' + ('0' + m).slice(-2);
}

const match = items.find(ev => {
  const title = norm(ev.summary); // também remove acentos do título
  const start = ev.start?.dateTime || ev.start?.date || '';
  const startTime = toBRT(start);

  const nameMatch = nameParts.length > 0 && nameParts.some(part => title.includes(part));
  const timeMatch = !timeKey || startTime === timeKey;
  return nameMatch && timeMatch;
});

if (!match) {
  return [{ json: {
    sucesso: false,
    event_id: null,
    mensagem: 'Agendamento não encontrado na agenda para os dados informados.'
  } }];
}

return [{ json: {
  sucesso: true,
  event_id: match.id,
  event_title: match.summary,
  event_start: match.start?.dateTime || match.start?.date,
  client_name: ctx.client_name,
  cancel_date: ctx.cancel_date,
  cancel_time: ctx.cancel_time
} }];

const ev = $('Encontra Evento').first().json;

const mensagem =
  '✅ Agendamento cancelado com sucesso!\n\n' +
  '📋 *Resumo do cancelamento:*\n' +
  '• Cliente: ' + ev.client_name + '\n' +
  '• Data: ' + ev.cancel_date + '\n' +
  '• Horário: ' + ev.cancel_time + '\n\n' +
  'O agendamento foi removido da agenda 🌿';

const notificacao =
  '❌ *Cancelamento de Agendamento — Damares Estética*\n\n' +
  '• Cliente: ' + ev.client_name + '\n' +
  '• Data: ' + ev.cancel_date + '\n' +
  '• Horário: ' + ev.cancel_time + '\n' +
  '• Evento: ' + (ev.event_title || '') + '\n\n' +
  'O evento foi removido da agenda automaticamente.';

return [{ json: { sucesso: true, mensagem, notificacao } }];

const response = $input.first().json;
const dados = $('Prepara Dados do Evento').first().json;
const items = response.items || [];

// Remove acentos para comparação
function norm(s) {
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

const nameKey = norm(dados.client_name);
const nameParts = nameKey.split(/\s+/).filter(p => p.length > 2);

const duplicate = items.find(ev => {
  const title = norm(ev.summary);
  return nameParts.length > 0 && nameParts.some(part => title.includes(part));
});

if (duplicate) {
  return [{ json: {
    duplicado: true,
    mensagem: 'Já existe um agendamento para ' + dados.client_name + ' em ' + dados.dateDisplay + ' às ' + dados.time + '. Agendamento não duplicado. Para reagendar, cancele o anterior primeiro.'
  } }];
}

return [{ json: { duplicado: false, ...dados } }];

const msg = ($('Coleta').first().json.mensagem || '').trim();

// Extract phone: "AVALIAÇÃO 11999887766" or "AVALIACAO 5511999887766"
const parts = msg.split(/\s+/);
let phone = (parts[1] || '').replace(/\D/g, '');

// Normalize to E.164 with country code 55
if (phone.startsWith('0')) phone = phone.slice(1);
if (!phone.startsWith('55')) phone = '55' + phone;

if (phone.length < 12 || phone.length > 13) {
  return [{ json: {
    valido: false,
    phone: '',
    erro: 'Número inválido. Use: AVALIAÇÃO 11XXXXXXXXX'
  } }];
}

return [{ json: {
  valido: true,
  phone: phone + '@s.whatsapp.net',
  phoneDisplay: phone
} }];

const conf = $('Formata Confirmação Agendamento').first().json;
return [{ json: {
  sucesso:    true,
  mensagem:   conf.mensagem,
  sinalFmt:   conf.sinalFmt,
  sinalValor: conf.sinalValor,
  service:    conf.service,
  dateDisplay:conf.dateDisplay,
  time:       conf.time,
  endTime:    conf.endTime
} }];

const conf = $('Formata Confirmação Cancelamento').first().json;
return [{ json: {
  sucesso:  true,
  mensagem: conf.mensagem
} }];

const agrupado = $('AGRUPA MENSAGENS').first().json.concatenated_content || '';
const tel = $('Coleta').first().json.telefone || '';
const crm = $input.first().json;
let ctx = '';
if (crm && crm.telefone) {
  const dt = crm.ultimo_atendimento
    ? new Date(crm.ultimo_atendimento).toLocaleDateString('pt-BR', { day:'2-digit', month:'2-digit', year:'numeric' })
    : 'nenhum';
  const parts = [
    '[CONTEXTO_SISTEMA]',
    'Nome: ' + (crm.nome || ''),
    'Total de atendimentos: ' + (crm.total_atendimentos || 0),
    'Ultimo procedimento: ' + (crm.ultimo_procedimento || 'nenhum'),
    'Ultimo atendimento: ' + dt,
    'Avaliacao confirmada: ' + (crm.avaliacao_confirmada ? 'SIM' : 'NAO'),
    'Status: ' + (crm.status || 'ativo'),
    '[/CONTEXTO_SISTEMA]',
    ''
  ];
  ctx = parts.join('\n') + '\n';
}
return [{ json: { enriched_text: ctx + agrupado, telefone: tel } }];
